5	namespace AtrioTeam\DigitalHub\Tags\Filament;
6	
7	use AtrioTeam\DigitalHub\Filament\Forms\Components\NestedCheckboxSelect;
8	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
9	use AtrioTeam\DigitalHub\Tags\Models\Tag;
10	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
11	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
12	use Closure;
13	use Filament\Forms\Components\Select;
14	use Filament\Schemas\Components\Fieldset;
15	use Filament\Schemas\Components\Section;
16	use Illuminate\Database\Eloquent\Builder;
17	
18	/**
19	 * Sezione dei tag associabili, con vincolo rigido: considera solo i gruppi
20	 * filtrati per l'entità data e per il target dato (entity|asset) e produce,
21	 * per ogni gruppo, un Fieldset con un unico NestedCheckboxSelect le cui
22	 * categorie collassabili sono le TagCategory del gruppo. Condiviso fra i form
23	 * delle entità e il picker degli asset nell'AssetManager.
24	 */
25	class TagPicker
26	{
27	    /**
28	     * Picker legato alla relazione `tags` del record del form (entità che usa
29	     * HasTags): ogni NestedCheckboxSelect di gruppo carica/sincronizza sul
30	     * pivot `taggables` i soli tag delle proprie categorie (il suo
31	     * "universo"), senza toccare quelli degli altri gruppi che condividono la
32	     * stessa relazione.
33	     *
34	     * `$scopeGroupsUsing` (opzionale) restringe ulteriormente i gruppi: riceve
35	     * la query dei TagGroup come parametro nominato `query` e viene valutata da
36	     * Filament, quindi supporta l'injection dei parametri di contesto (es.
37	     * `$livewire`). Permette all'app vincoli propri (es. la Destinazione
38	     * Category1) senza che il package li conosca.
39	     */
40	    public static function make(string $entityAlias, TagTarget $target, ?Closure $scopeGroupsUsing = null): Section
41	    {
42	        // schema lazy: i gruppi possono dipendere dal contesto ($livewire) via
43	        // $scopeGroupsUsing, valutato da Filament sul componente
44	        return self::section()->schema(function (Section $component) use ($entityAlias, $target, $scopeGroupsUsing): array {
45	            $scopeGroups = $scopeGroupsUsing === null ? null : function (Builder $groupQuery) use ($component, $scopeGroupsUsing): void {
46	                $component->evaluate($scopeGroupsUsing, ['query' => $groupQuery]);
47	            };
48	
49	            return array_map(
50	                fn (TagGroup $group): Fieldset => self::relationshipGroupFieldset($group),
51	                self::groups($entityAlias, $target, $scopeGroups),
52	            );
53	        });
54	    }
55	
56	    /**
57	     * Picker "standalone" (senza relationship): lo stato è un array di id tag
58	     * per categoria, sotto la chiave `tags` (`tags.{categoryId}` => int[]).
59	     * Per contesti senza record bindato al form (es. azione nell'AssetManager),
60	     * dove fill/sync sono gestiti a mano dal chiamante.
61	     */
62	    public static function makeStandalone(string $entityAlias, TagTarget $target): Section
63	    {
64	        return self::section()->schema(fn (): array => array_map(
65	            self::groupFieldset(...),
66	            self::groups($entityAlias, $target, null),
67	        ));
68	    }
69	
70	    private static function section(): Section
71	    {
72	        return Section::make(__('digital-hub::tag.model_plural'));
73	    }
74	
75	    /**
76	     * Fieldset del gruppo per la variante standalone, con un select per ogni
77	     * sua categoria (con almeno un tag).
78	     */
79	    private static function groupFieldset(TagGroup $group): Fieldset
80	    {
81	        return Fieldset::make((string) $group->name)
82	            ->columns(2)
83	            ->columnSpanFull()
84	            ->schema(
85	                $group->categories
86	                    ->filter(fn (TagCategory $category): bool => $category->tags->isNotEmpty())
87	                    ->sortBy('id')
88	                    ->map(self::categorySelect(...))
89	                    ->values()
90	                    ->all(),
91	            );
92	    }
93	
94	    /**
95	     * Fieldset del gruppo per la variante con relationship: un unico
96	     * NestedCheckboxSelect le cui categorie collassabili sono le TagCategory
97	     * del gruppo (con almeno un tag) e i cui item sono i loro tag. Lo stato è
98	     * caricato/salvato sulla relazione `tags`, ristretto all'universo dei tag
99	     * di queste categorie: più Fieldset di gruppo possono così condividere la
100	     * stessa relazione senza toccare le selezioni degli altri gruppi.
101	     */
102	    private static function relationshipGroupFieldset(TagGroup $group): Fieldset
103	    {
104	        $categories = $group->categories
105	            ->filter(fn (TagCategory $category): bool => $category->tags->isNotEmpty())
106	            ->sortBy('id')
107	            ->values();
108	
109	        return Fieldset::make((string) $group->name)
110	            ->columnSpanFull()
111	            ->schema([
112	                NestedCheckboxSelect::make('tags_group_' . $group->id)
113	                    ->hiddenLabel()
114	                    ->relationship('tags', Tag::class, TagCategory::class, 'tag_category_id', '')
115	                    ->categories($categories)
116	                    ->items($categories->flatMap(fn (TagCategory $category) => $category->tags)),
117	            ]);
118	    }
119	
120	    /**
121	     * Select multiplo con i tag della categoria come opzioni. Lo statePath
122	     * annidato `tags.{categoryId}` tiene tutte le selezioni sotto `tags`.
123	     */
124	    private static function categorySelect(TagCategory $category): Select
125	    {
126	        $options = [];
127	        foreach ($category->tags as $tag) {
128	            $options[(int) $tag->id] = (string) $tag->name;
129	        }
130	
131	        return Select::make('tags.' . (int) $category->id)
132	            ->label((string) $category->name)
133	            ->multiple()
134	            ->searchable()
135	            ->options($options)
136	            ->default([]);
137	    }
138	
139	    /**
140	     * Gruppi filtrati per entità e target, più l'eventuale vincolo aggiuntivo
141	     * passato dal chiamante, con le loro categorie (e relativi tag). Le
142	     * categorie senza tag e i gruppi rimasti senza categorie sono esclusi.
143	     *
144	     * @param (Closure(Builder<TagGroup>): void)|null $scopeGroups query dei TagGroup
145	     * @return array<int, TagGroup>
146	     */
147	    private static function groups(string $entityAlias, TagTarget $target, ?Closure $scopeGroups): array
148	    {
149	        $groupQuery = TagGroup::query()
150	            ->where('entity_type', $entityAlias)
151	            ->where('target', $target->value)
152	            ->whereHas('categories', function (Builder $categoryQuery): void {
153	                $categoryQuery->whereHas('tags');
154	            })
155	            ->with('categories.tags')
156	            ->orderBy('id');
157	
158	        if ($scopeGroups !== null) {
159	            $scopeGroups($groupQuery);
160	        }
161	
162	        return $groupQuery->get()->all();
163	    }
164	}
